python - <<'PY'
import limited_client as robot, numpy as np
for cam in ['topview','gripperPOV']:
 o=robot.observe(cam); print('\n',cam,'K=',o['intrinsic'],'\nT=',o['camera_to_world'])
 if cam=='topview':
  K=o['intrinsic']; T=o['camera_to_world']; dep=o['depth_m']
  for uv in [(196,138),(199,155),(259,145),(260,160),(240,180),(225,180),(180,160),(275,200),(200,200)]:
   u,v=uv; d=float(dep[v,u]); p=np.linalg.inv(K)@np.array([u,v,1.])*d; w=T@np.r_[p,1.]; print(uv,d,w[:3])
PY

